<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\OAuth\MagicLink\Application\Usecase\VerifyMagicLink;

use Civi\Lughauth\Features\Access\Tenant\Domain\Gateway\TenantReadGateway;
use Civi\Lughauth\Features\Access\User\Domain\Gateway\UserReadGateway;
use Civi\Lughauth\Features\OAuth\MagicLink\Domain\Gateway\MagicLinkGateway;
use Civi\Lughauth\Features\OAuth\MagicLink\Domain\Gateway\MagicLinkCodeGateway;
use Civi\Lughauth\Features\OAuth\MagicLink\Domain\Gateway\MagicLinkEnabledGateway;
use Civi\Lughauth\Features\OAuth\MagicLink\Domain\Gateway\MagicLinkSessionGateway;

/**
 * Application use case that validates a magic-link token and exchanges it for an OAuth authorization code.
 *
 * Performs a multi-step verification pipeline: feature-flag check, hash lookup, expiry and single-use
 * invariant enforcement, and client-id binding. On success the token is marked as used, a short-lived
 * authorization code is created via the MagicLinkCodeGateway, and a browser session is optionally
 * established via the MagicLinkSessionGateway. Any failure raises a \DomainException with
 * the OAuth error code 'invalid_grant', ensuring the caller never reveals the specific reason
 * for rejection to the end user.
 */
class VerifyMagicLinkUsecase
{
    public function __construct(
        private readonly MagicLinkGateway $gateway,
        private readonly MagicLinkCodeGateway $codeGateway,
        private readonly MagicLinkEnabledGateway $enabled,
        private readonly MagicLinkSessionGateway $sessionGateway,
        private readonly TenantReadGateway $tenants,
        private readonly UserReadGateway $users,
    ) {
    }

    /**
     * Verifies a raw magic-link token, marks it used, creates an authorization code, and returns
     * the redirect URL and session. Throws \DomainException with code 'invalid_grant' on any
     * failure including disabled feature, missing or expired token, or client-id mismatch.
     */
    public function verify(string $rawToken, string $clientId, string $tenantId): MagicLinkVerifyResult
    {
        if (!$this->enabled->isEnabled($tenantId)) {
            throw new \DomainException('invalid_grant');
        }

        $tokenHash = hash('sha256', $rawToken);
        $magicLink = $this->gateway->findByHash($tokenHash, $tenantId);

        if ($magicLink === null || !$magicLink->isValid()) {
            throw new \DomainException('invalid_grant');
        }

        if ($magicLink->clientId !== $clientId) {
            throw new \DomainException('invalid_grant');
        }

        $this->gateway->markUsed($magicLink->uid);

        $authCode = $this->codeGateway->createAuthCode(
            userUid: $magicLink->userUid,
            clientId: $clientId,
            scope: $magicLink->scope,
            redirectUri: $magicLink->redirectUri,
            tenant: $tenantId,
            nonce: $magicLink->nonce,
        );

        $redirectUrl = $magicLink->redirectUri . '?code=' . urlencode($authCode);
        if ($magicLink->state !== null && $magicLink->state !== '') {
            $redirectUrl .= '&state=' . urlencode($magicLink->state);
        }

        $tenant = $this->tenants->findOneByName($tenantId);
        $tenantUid = $tenant?->uid() ?? '';

        $user = $this->users->findOneByUid($magicLink->userUid);
        $email = $user?->getName() ?? $magicLink->userUid;

        $session = $this->sessionGateway->createSession(
            userUid: $magicLink->userUid,
            email: $email,
            tenantUid: $tenantUid,
            tenantName: $tenantId,
            clientId: $clientId,
        );

        return new MagicLinkVerifyResult(
            redirectUrl: $redirectUrl,
            session: $session,
        );
    }
}
